Out of curiousity, tested quick and dirty template build with path caching (code is written by me, though it doesn't handle the edge cases).

<details>
<summary>(partial) SAFData.kt</summary>

```kt
private val CACHE = HashMap<String, HashMap<String, String>>();

private fun resolvePath(context: Context, path: String, accessFlag: FileAccessFlags): Uri {
    val uri = path.toUri()
    val fragment = uri.fragment

    if (fragment == null) {
        return uri
    }

    // For directory format: content://treeUri#relative/path/to/file
    val treeUri = uri.buildUpon().fragment(null).build()
    val relativePath = fragment
    val resolver = context.contentResolver

    val parts = relativePath.split('/')
    val filename = parts.last()
    val folderParts = parts.dropLast(1)

    var parentDocumentId = DocumentsContract.getTreeDocumentId(treeUri)

    val isWriteMode = when (accessFlag) {
        FileAccessFlags.WRITE,
        FileAccessFlags.READ_WRITE,
        FileAccessFlags.WRITE_READ -> true
        else -> false
    }

    for (folder in folderParts) {
        val directory = CACHE.getOrPut(parentDocumentId) {
            val current = DocumentsContract.buildChildDocumentsUriUsingTree(treeUri, parentDocumentId)
            val result = HashMap<String, String>()
            resolver.query(current, arrayOf(
                DocumentsContract.Document.COLUMN_DISPLAY_NAME,
                DocumentsContract.Document.COLUMN_DOCUMENT_ID),
                null, null, null)
            ?.use { cursor ->
                while (cursor.moveToNext()) {
                    val displayName = cursor.getString(0);
                    val documentId = cursor.getString(1);
                    result[displayName] = documentId;
                }
            }
            result
        }

        parentDocumentId = directory.getOrPut(folder) {
            if (!isWriteMode) {
                throw IllegalStateException("Directory not found: $folder")
            }
            val createdUri = DocumentsContract.createDocument(resolver,
                DocumentsContract.buildDocumentUriUsingTree(treeUri, parentDocumentId),
                DocumentsContract.Document.MIME_TYPE_DIR,
                folder)
                ?: throw IllegalStateException("Failed to create directory: $folder")
            DocumentsContract.getDocumentId(createdUri)
        }
    }

    val fileDirectory = CACHE.getOrPut(parentDocumentId) {
        val current = DocumentsContract.buildChildDocumentsUriUsingTree(treeUri, parentDocumentId)
        val result = HashMap<String, String>()
        resolver.query(current, arrayOf(
            DocumentsContract.Document.COLUMN_DISPLAY_NAME,
            DocumentsContract.Document.COLUMN_DOCUMENT_ID),
            null, null, null)
        ?.use { cursor ->
            while (cursor.moveToNext()) {
                val displayName = cursor.getString(0);
                val documentId = cursor.getString(1);
                result[displayName] = documentId;
            }
        }
        result
    }

    return DocumentsContract.buildDocumentUriUsingTree(
        treeUri, fileDirectory.getOrPut(filename) {
            if (!isWriteMode) {
                throw IllegalStateException("File not found: $filename")
            }
            val createdUri = DocumentsContract.createDocument(resolver,
                DocumentsContract.buildDocumentUriUsingTree(treeUri, parentDocumentId),
                "application/octet-stream",
                filename)
                ?: throw IllegalStateException("Failed to create file: $filename")
            DocumentsContract.getDocumentId(createdUri)
        }
    )
}
```

</details>

The performance is still bad, but it's been improved by a lot, enough for load times to be snappy and not miserable, at least.
